package com.chain.ratelimit

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future}

// Deployed as a sidecar in K8s pod alongside the blockchain node
// Rate limiter for smart contract transaction submissions

case class TxSubmission(sender: String, contractAddr: String, nonce: Long, timestamp: Long, payload: Array[Byte])

class WindowCounter(val windowSizeMs: Long, val maxRequests: Int) {
  private val windows = new ConcurrentHashMap[String, AtomicLong]()
  private val windowTimestamps = new ConcurrentHashMap[String, Long]()

  def getWindowKey(sender: String, currentTime: Long): String = {
    val windowId = currentTime / windowSizeMs
    s"${sender}:${windowId}"
  }

  def increment(sender: String, currentTime: Long): Long = {
    val key = getWindowKey(sender, currentTime)
    val counter = windows.computeIfAbsent(key, _ => new AtomicLong(0L))
    windowTimestamps.putIfAbsent(key, currentTime)
    counter.incrementAndGet()
  }

  def getCount(sender: String, currentTime: Long): Long = {
    val key = getWindowKey(sender, currentTime)
    val counter = windows.get(key)
    if (counter == null) 0L else counter.get()
  }

  def cleanup(currentTime: Long): Unit = {
    val expiry = currentTime - (windowSizeMs * 3)
    windowTimestamps.forEach { (key, ts) =>
      if (ts < expiry) {
        windows.remove(key)
        windowTimestamps.remove(key)
      }
    }
  }
}

trait NonceTracker {
  def validateAndTrack(sender: String, nonce: Long): Boolean
  def getLastNonce(sender: String): Long
}

class InMemoryNonceTracker extends NonceTracker {
  private val nonces = new ConcurrentHashMap[String, AtomicLong]()

  override def validateAndTrack(sender: String, nonce: Long): Boolean = {
    val lastNonce = nonces.computeIfAbsent(sender, _ => new AtomicLong(0L))
    // Retry loop: only accept the nonce if we actually win the CAS.
    // This prevents concurrent duplicate/replayed nonces from all being accepted.
    while (true) {
      val current = lastNonce.get()
      if (nonce > current) {
        if (lastNonce.compareAndSet(current, nonce)) {
          return true
        }
        // Lost the race; re-read and re-evaluate against the new current value.
      } else {
        return false
      }
    }
    false // unreachable, satisfies type checker
  }

  override def getLastNonce(sender: String): Long = {
    val n = nonces.get(sender)
    if (n == null) 0L else n.get()
  }
}

class ContractRateLimiter(
  windowSizeMs: Long = 60000L,
  maxTxPerWindow: Int = 10,
  maxGlobalTxPerWindow: Int = 1000,
  burstMultiplier: Int = 2
) {
  private val perSenderCounter = new WindowCounter(windowSizeMs, maxTxPerWindow)
  private val globalCounter = new WindowCounter(windowSizeMs, maxGlobalTxPerWindow)
  private val nonceTracker: NonceTracker = new InMemoryNonceTracker()
  private val replayWindow = new ConcurrentHashMap[String, java.util.Set[Long]]()

  // K8s pod identity derived from downward API
  private val podOrdinal: Int = sys.env.getOrElse("POD_ORDINAL", "0").toInt
  private val totalReplicas: Int = sys.env.getOrElse("TOTAL_REPLICAS", "3").toInt

  // Distributed rate limit adjustment: each pod handles 1/N of the limit
  // But we apply a burst multiplier to handle uneven distribution
  private val effectivePerSenderLimit: Int = {
    val baseLimit = maxTxPerWindow / totalReplicas
    val adjusted = baseLimit * burstMultiplier
    adjusted
  }

  private val effectiveGlobalLimit: Int = {
    val baseLimit = maxGlobalTxPerWindow / totalReplicas
    baseLimit * burstMultiplier
  }

  def shouldAllow(tx: TxSubmission): RateLimitResult = {
    val now = System.currentTimeMillis()

    // Step 1: Validate timestamp freshness (anti-replay)
    val txAge = now - tx.timestamp
    if (txAge > windowSizeMs * 2 || txAge < -30000L) {
      return RateLimitResult(allowed = false, reason = "stale_or_future_tx")
    }

    // Step 2: Nonce validation
    if (!nonceTracker.validateAndTrack(tx.sender, tx.nonce)) {
      return RateLimitResult(allowed = false, reason = "invalid_nonce")
    }

    // Step 3: Per-sender rate check using SERVER TIME for window calculation
    // Ensures attacker cannot manipulate window placement
    val senderCount = perSenderCounter.increment(tx.sender, now)
    if (senderCount > effectivePerSenderLimit) {
      return RateLimitResult(allowed = false, reason = "sender_rate_exceeded")
    }

    // Step 4: Global rate check
    val globalCount = globalCounter.increment("__global__", now)
    if (globalCount > effectiveGlobalLimit) {
      return RateLimitResult(allowed = false, reason = "global_rate_exceeded")
    }

    // Periodic cleanup
    if (globalCount % 100 == 0) {
      perSenderCounter.cleanup(now)
      globalCounter.cleanup(now)
    }

    RateLimitResult(allowed = true, reason = "ok")
  }
}

case class RateLimitResult(allowed: Boolean, reason: String)

// gRPC service handler for the rate limiter sidecar
class RateLimitService(limiter: ContractRateLimiter)(implicit ec: ExecutionContext) {

  def checkTransaction(request: TxSubmission): Future[RateLimitResult] = Future {
    limiter.shouldAllow(request)
  }

  def healthCheck(): Future[Boolean] = Future.successful(true)
}

object RateLimiterApp extends App {
  implicit val ec: ExecutionContext = ExecutionContext.global
  val limiter = new ContractRateLimiter()
  val service = new RateLimitService(limiter)
  println(s"Rate limiter sidecar started on pod ordinal ${sys.env.getOrElse("POD_ORDINAL", "0")}")
}
